  "Alert on unresolved items: Off means only a crashed or aborted run sends the failure callback. On also sends failure when a run finishes with unresolved items or provider errors, such as a destination rejecting a write. The run itself still counts as successful in CrossWatch.": "Bei offenen Elementen warnen: Aus bedeutet, dass nur ein abgestürzter oder abgebrochener Lauf den Fehler-Callback sendet. An sendet den Fehler auch, wenn ein Lauf mit offenen Elementen oder Anbieterfehlern endet, etwa wenn ein Ziel einen Schreibvorgang ablehnt. In CrossWatch gilt der Lauf trotzdem als erfolgreich.",
  "Alert when a provider sign-in is lost: Sends provider_auth_lost when a provider profile used by an enabled sync pair, watcher route or scrobble webhook needs a new sign-in, and provider_auth_recovered when it works again. Each change is sent once. A provider that is only unreachable does not send an alert. CrossWatch JSON sends these to the All events URL.": "Warnen, wenn eine Anbieter-Anmeldung verloren geht: Sendet provider_auth_lost, wenn ein Anbieterprofil, das von einem aktiven Sync-Paar, einer Watcher-Route oder einem Scrobble-Webhook genutzt wird, eine neue Anmeldung braucht, und provider_auth_recovered, wenn es wieder funktioniert. Jede Änderung wird einmal gesendet. Ein nur nicht erreichbarer Anbieter löst keine Warnung aus. CrossWatch JSON sendet diese an die URL «Alle Ereignisse».",
  "Alert when the watcher stops: Sends watcher_stopped when an enabled watcher route is not running, and watcher_recovered when it runs again. Each change is sent once. This includes a watcher that was stopped by hand or never started. Turning the watcher source or the route off does not send an alert. CrossWatch JSON sends these to the All events URL.": "Warnen, wenn der Watcher stoppt: Sendet watcher_stopped, wenn eine aktive Watcher-Route nicht läuft, und watcher_recovered, wenn sie wieder läuft. Jede Änderung wird einmal gesendet. Das gilt auch für einen Watcher, der von Hand gestoppt oder nie gestartet wurde. Das Ausschalten der Watcher-Quelle oder der Route löst keine Warnung aus. CrossWatch JSON sendet diese an die URL «Alle Ereignisse».",
