  "All separate parts must be watched before the combined episode is marked watched. A watched combined episode expands into its parts, following the pair’s sync direction.": "Alle Einzelteile müssen gesehen sein, bevor die kombinierte Episode als gesehen gilt. Eine gesehene kombinierte Episode wird in ihre Teile aufgeteilt, gemäss der Abgleichrichtung des Paars.",
