  "Allow mass delete": "Massenlöschung erlauben",
  "Allow mass delete If off, blocks large delete plans (roughly >10%). Enable for first runs. It's either mass-delete or drop-guard or none; not both.": "Massenlöschung erlauben: Wenn aus, werden grosse Löschpläne (ab etwa 10 %) blockiert. Für erste Läufe einschalten. Entweder Massenlöschung oder Drop-Guard oder keines, nicht beides.",
  "Allow PMS fallback": "PMS-Rückfall erlauben",
  "Allow repeat watches for this destination. Requires SIMKL Pro or VIP. SIMKL applies a 48-hour gap per movie or episode. Your watched threshold still applies, with a minimum of 80%.": "Wiederholte Sichtungen für dieses Ziel erlauben. Setzt SIMKL Pro oder VIP voraus. SIMKL verlangt 48 Stunden Abstand pro Film oder Episode. Deine Gesehen-Schwelle gilt weiterhin, mindestens 80 %.",
  "Allow repeat watches on this route. Requires SIMKL Pro or VIP. SIMKL applies a 48-hour gap per movie or episode. Your watched threshold still applies, with a minimum of 80%.": "Wiederholte Sichtungen auf dieser Route erlauben. Setzt SIMKL Pro oder VIP voraus. SIMKL verlangt 48 Stunden Abstand pro Film oder Episode. Deine Gesehen-Schwelle gilt weiterhin, mindestens 80 %.",
  "Almost done": "Fast fertig",
  "Already in queue": "Bereits in der Warteschlange",
