  "Also excluded by a block rule": "Zusätzlich durch eine Sperrregel ausgeschlossen",
  "Also report a run as failed when it ends with unresolved items or provider errors.": "Einen Lauf auch als fehlgeschlagen melden, wenn er mit offenen Elementen oder Anbieterfehlern endet.",
  "Also snapshots, sync reports and caches. The largest backup.": "Zusätzlich Snapshots, Abgleichberichte und Caches. Die grösste Sicherung.",
  "Also use for completed scrobbles": "Auch für abgeschlossene Scrobbles verwenden",
