  "Analyze": "Analysieren",
  "Analyze the latest sync run in the sync log. Tell me what happened and whether anything went wrong.": "Analysiere den letzten Abgleichlauf im Abgleich-Protokoll. Sag mir, was passiert ist und ob etwas schiefging.",
  "Analyze the recent debug log and point out any errors or warnings that matter.": "Analysiere das aktuelle Debug-Protokoll und weise auf wichtige Fehler oder Warnungen hin.",
  "Analyze the recent watcher log. Is scrobbling working, and did anything go wrong?": "Analysiere das aktuelle Watcher-Protokoll. Funktioniert das Scrobbeln, und ist etwas schiefgegangen?",
  "Analyze the {0} log session {1} ({2}, started {3}). Tell me what happened and whether anything went wrong.": "Analysiere die {0}-Protokollsitzung {1} ({2}, gestartet {3}). Sag mir, was passiert ist und ob etwas schiefging.",
  "Analyze this log with AI": "Dieses Protokoll mit KI analysieren",
  "Analyzed at {0}": "Analysiert am {0}",
  "Analyzed locally from enabled pair features. Media filters, library scopes and sync safeguards can reduce actual overlap. No provider data is changed.": "Lokal aus den aktiven Paar-Funktionen analysiert. Medienfilter, Mediatheks-Bereiche und Abgleich-Schutzmechanismen können die tatsächliche Überschneidung verringern. Es werden keine Anbieterdaten geändert.",
