  "and this code.": "und diesen Code.",
  "AniBridge handles episode numbering across AniDB, MyAnimeList, AniList, TMDB and TVDB. animeApi adds SIMKL and Kitsu identity.": "AniBridge übernimmt die Episodennummerierung über AniDB, MyAnimeList, AniList, TMDB und TVDB. animeApi ergänzt SIMKL- und Kitsu-Kennungen.",
  "AniList Authentication": "AniList-Anmeldung",
