  "AniList needs Anime ID Mapping": "AniList braucht Anime-ID-Zuordnung",
  "AniList uses Anime ID Mapping": "AniList nutzt Anime-ID-Zuordnung",
  "AniList, BingeBase, CW local tracker, Emby, FlickList, Floppy, Jellyfin, Kitsu, Kodi, MDBList, Nuvio, Plex, PublicMetaDB, PunchPlay, Scrob, SIMKL, Stremio, Tautulli, TMDb, Tracearr, Trakt and WeTrakr": "AniList, BingeBase, CW-Lokaltracker, Emby, FlickList, Floppy, Jellyfin, Kitsu, Kodi, MDBList, Nuvio, Plex, PublicMetaDB, PunchPlay, Scrob, SIMKL, Stremio, Tautulli, TMDb, Tracearr, Trakt und WeTrakr",
  "Anime episode mapping": "Anime-Episodenzuordnung",
  "Anime episode mapping Translate anime episode numbering before writing progress to SIMKL, using the local Anime ID database. Requires global Anime ID Mapping. This can heavily increase API calls when additional anime ID and episode lookups are needed.": "Anime-Episodenzuordnung: Rechnet die Anime-Episodennummerierung mit der lokalen Anime-ID-Datenbank um, bevor der Fortschritt an SIMKL geschrieben wird. Setzt die globale Anime-ID-Zuordnung voraus. Kann deutlich mehr API-Aufrufe verursachen, wenn zusätzliche Anime-ID- und Episodenabfragen nötig sind.",
  "Anime episode mapping Translate anime episode numbering when this history pair writes to an anime tracker, using the local Anime ID database. Requires a TMDB metadata key and global Anime ID Mapping. This can heavily increase API calls when additional anime ID and episode lookups are needed.": "Anime-Episodenzuordnung: Rechnet die Anime-Episodennummerierung mit der lokalen Anime-ID-Datenbank um, wenn dieses Verlaufs-Paar in einen Anime-Tracker schreibt. Setzt einen TMDB-Metadatenschlüssel und die globale Anime-ID-Zuordnung voraus. Kann deutlich mehr API-Aufrufe verursachen, wenn zusätzliche Anime-ID- und Episodenabfragen nötig sind.",
  "Anime ID custom mappings": "Eigene Anime-ID-Zuordnungen",
