  "Anime-only sync": "Nur Anime abgleichen",
  "Anime-only sync Only sync items that Anime ID Mapping can confirm as anime. Non-anime and unmapped items are skipped before falling back to a title search.": "Nur Anime abgleichen: Nur Elemente abgleichen, die die Anime-ID-Zuordnung als Anime bestätigen kann. Nicht-Anime und nicht zugeordnete Elemente werden übersprungen, bevor auf eine Titelsuche zurückgegriffen wird.",
  "Anime-only sync Only sync ratings for items that Anime ID Mapping can confirm as anime. Non-anime and unmapped items are skipped before falling back to a title search.": "Nur Anime abgleichen: Nur Bewertungen von Elementen abgleichen, die die Anime-ID-Zuordnung als Anime bestätigen kann. Nicht-Anime und nicht zugeordnete Elemente werden übersprungen, bevor auf eine Titelsuche zurückgegriffen wird.",
