  "Blackbox state": "Blackbox-Status",
  "Blackbox Unresolved is only a reporting state: items that fail to write are recorded, shown in diagnostics, and retried on every sync. Blackbox is the quarantine state and the only thing that stops an item from being planned again.": "Blackbox: «Offen» ist nur ein Berichtsstatus: Elemente, die nicht geschrieben werden können, werden erfasst, in der Diagnose angezeigt und bei jedem Abgleich erneut versucht. Blackbox ist der Quarantäne-Status und das Einzige, was verhindert, dass ein Element erneut eingeplant wird.",
  "Blackbox: Enabled Automatic flapper protection and failure quarantine.": "Blackbox: Aktiviert. Automatischer Schutz vor Flattern und Quarantäne bei Fehlern.",
  "Blackbox: Pair scoped Keep blackbox decisions per pair instead of global.": "Blackbox: Pro Paar. Blackbox-Entscheide pro Paar statt global speichern.",
