  "Click Connect BingeBase and approve the code at bingebase.com/activate. BingeBase only provides scrobble.": "Klicke auf «BingeBase verbinden» und bestätige den Code auf bingebase.com/activate. BingeBase bietet nur Scrobbeln.",
  "Click Connect Plex to get a link code. CrossWatch shows the code, then opens plex.tv/link so you can enter it and approve access. Next, validate the server URL and optionally whitelist libraries.": "Klicke auf «Plex verbinden», um einen Verknüpfungscode zu erhalten. CrossWatch zeigt den Code und öffnet plex.tv/link, wo du ihn eingibst und den Zugriff bestätigst. Danach prüfst du die Server-URL und kannst Mediatheken freigeben.",
  "Click Connect Plex, then use the link code shown here in the browser window. Once the account is connected, CrossWatch will move you to Settings to validate the server.": "Klicke auf «Plex verbinden» und gib den hier angezeigten Verknüpfungscode im Browserfenster ein. Sobald das Konto verbunden ist, führt dich CrossWatch zu den Einstellungen, um den Server zu prüfen.",
  "Click Connect PunchPlay and approve the code at punchplay.tv/link. No API keys are needed - CrossWatch ships its own PunchPlay app id.": "Klicke auf «PunchPlay verbinden» und bestätige den Code auf punchplay.tv/link. Es braucht keine API-Schlüssel, CrossWatch bringt eine eigene PunchPlay-App-ID mit.",
