  "Collections": "Sammlungen",
  "Collections are one-way only. Disable Collections to use two-way sync.": "Sammlungen gehen nur in eine Richtung. Deaktiviere Sammlungen, um beidseitig abzugleichen.",
  "Collections could not be loaded": "Sammlungen konnten nicht geladen werden",
  "Collections could not be loaded.": "Sammlungen konnten nicht geladen werden.",
  "Collections group titles in the library, playlists keep their own order.": "Sammlungen gruppieren Titel in der Mediathek, Playlists behalten ihre eigene Reihenfolge.",
  "Collections per month": "Sammlungen pro Monat",
  "Collections | Basics": "Sammlungen | Grundlagen",
  "Collections | Options": "Sammlungen | Optionen",
  "Collections: Read from media server Reads resolution, HDR and audio from the media server and sends them with new collection items. Adds some extra load on the media server while reading the library.": "Sammlungen: Vom Medienserver lesen. Liest Auflösung, HDR und Ton vom Medienserver und sendet sie mit neuen Sammlungselementen. Belastet den Medienserver beim Lesen der Mediathek etwas mehr.",
  "Collections: Update existing items When the media info of an item changes on the source (for example 1080p to 4K, or a new Atmos track), the item on the destination is updated too. Only fills in or changes values, never clears them. Physical copies on the destination are left alone. The first sync can update many items.": "Sammlungen: Bestehende Elemente aktualisieren. Ändern sich die Medieninfos eines Elements in der Quelle (zum Beispiel von 1080p auf 4K oder eine neue Atmos-Tonspur), wird das Element im Ziel ebenfalls aktualisiert. Werte werden nur ergänzt oder geändert, nie gelöscht. Physische Kopien im Ziel bleiben unberührt. Der erste Abgleich kann viele Elemente aktualisieren.",
