  "Compare the recorded watch times and playback history. Matching IDs do not establish whether these are the same playback or separate watches. A mapping edit does not correct the watch time.": "Vergleiche die erfassten Wiedergabezeiten und den Wiedergabeverlauf. Gleiche IDs zeigen nicht, ob es dieselbe Wiedergabe oder getrennte Sichtungen sind. Eine Änderung der Zuordnung korrigiert die Wiedergabezeit nicht.",
