  "Connect with a device code": "Mit Gerätecode verbinden",
  "Connect with a Device Code (recommended) or paste a legacy API key. Device Code opens a browser window so you can approve CrossWatch without sharing a key.": "Verbinde per Gerätecode (empfohlen) oder füge einen älteren API-Schlüssel ein. Der Gerätecode öffnet ein Browserfenster, in dem du CrossWatch bestätigst, ohne einen Schlüssel weiterzugeben.",
  "Connect with a PIN code (recommended) - CrossWatch shows a short code you enter at auth.trakt.tv/activate, no keys needed. Connecting with your own Trakt app credentials remains available.": "Mit PIN-Code verbinden (empfohlen): CrossWatch zeigt einen kurzen Code, den du auf auth.trakt.tv/activate eingibst, Schlüssel braucht es keine. Die Verbindung mit eigenen Trakt-App-Zugangsdaten bleibt möglich.",
  "Connect with a PIN code (recommended) - CrossWatch shows a short code you enter at simkl.com/pin, no keys needed. OAuth with your own SIMKL app credentials remains available.": "Mit PIN-Code verbinden (empfohlen): CrossWatch zeigt einen kurzen Code, den du auf simkl.com/pin eingibst, Schlüssel braucht es keine. OAuth mit eigenen SIMKL-App-Zugangsdaten bleibt möglich.",
