  "Create a new access key? Kometa, Radarr and Sonarr stop reading this list until you paste the new addresses.": "Neuen Zugriffsschlüssel erstellen? Kometa, Radarr und Sonarr lesen diese Liste nicht mehr, bis du die neuen Adressen einfügst.",
