  "Create an API token in Floppy Settings > Integrations, then connect your self-hosted server.": "Erstelle ein API-Token in Floppy unter Settings > Integrations und verbinde dann deinen selbst gehosteten Server.",
  "Create an app-state backup and compact the sync state database?": "Sicherung des App-Zustands erstellen und die Abgleich-Datenbank verdichten?",
  "Create an app-state backup and prune stale sync state? This removes provider or instance baselines that are no longer referenced by configured sync pairs or scrobbler routes, plus unresolved, blackbox and flap files left behind by removed pairs.": "Sicherung des App-Zustands erstellen und veralteten Abgleich-Zustand entfernen? Dies entfernt Anbieter- oder Instanz-Basisdaten, die von keinem eingerichteten Sync-Paar und keiner Scrobbler-Route mehr genutzt werden, sowie offene, Blackbox- und Flatter-Dateien entfernter Paare.",
