  "Deletions based on Source When enabled, this pair only removes items after CrossWatch observed them disappear from the source. When disabled, this pair runs mirror mode and removes target items missing from the source (destructive; use with care).": "Löschungen anhand der Quelle: Wenn aktiv, entfernt dieses Paar Elemente erst, nachdem CrossWatch gesehen hat, dass sie aus der Quelle verschwunden sind. Wenn inaktiv, läuft das Paar im Spiegelmodus und entfernt Ziel-Elemente, die in der Quelle fehlen (zerstörerisch, mit Vorsicht verwenden).",
