  "Each linked provider can update these values. Different ratings or playback positions for the same item may compete. This note does not mean a conflict has occurred.": "Jeder verknüpfte Anbieter kann diese Werte ändern. Unterschiedliche Bewertungen oder Wiedergabepositionen desselben Elements können sich überschneiden. Dieser Hinweis bedeutet nicht, dass ein Konflikt aufgetreten ist.",
