  "Emby: Strict ID matching": "Emby: Strikter ID-Abgleich",
  "Emby: Strict ID matching When enabled, CrossWatch only matches by IDs (Emby IDs + external IDs). Title/year searches are disabled. The pair Match by file path option can separately enable a file-path fallback.": "Emby: Strikter ID-Abgleich. Wenn aktiv, ordnet CrossWatch nur über IDs zu (Emby-IDs und externe IDs). Suchen nach Titel/Jahr sind deaktiviert. Die Paar-Option «Über Dateipfad zuordnen» kann separat einen Rückfall auf den Dateipfad aktivieren.",
  "Emby: Watchlist mode Emby has no native Watchlist. CrossWatch maps it to: • Favorites: sets the Favorite flag • Playlist: writes to a named playlist (episodes only; no shows) • Collections: writes to a named collection Changing mode does not move existing items. Tip: Favorites or Collections are the most compatible.": "Emby: Watchlist-Modus. Emby hat keine eigene Watchlist. CrossWatch bildet sie ab auf: • Favoriten: setzt die Favoriten-Markierung • Playlist: schreibt in eine benannte Playlist (nur Episoden, keine Serien) • Sammlungen: schreibt in eine benannte Sammlung. Ein Moduswechsel verschiebt bestehende Elemente nicht. Tipp: Favoriten oder Sammlungen sind am verträglichsten.",
  "Empties every event category and the sync activity calendar. Leaves the rest of the local database alone.": "Leert jede Ereigniskategorie und den Kalender der Abgleich-Aktivität. Der Rest der lokalen Datenbank bleibt unverändert.",
  "Empty = all libraries.": "Leer = alle Mediatheken.",
  "Empty = use connection-level whitelist.": "Leer = Freigabeliste der Verbindung verwenden.",
  "Empty = use server-level whitelist.": "Leer = Freigabeliste des Servers verwenden.",
