  "Enter your API key first.": "Gib zuerst deinen API-Schlüssel ein.",
  "Enter your Emby server URL, username and password, then sign in. CrossWatch will move you to Settings next so you can validate the server, pick the user, and optionally whitelist libraries.": "Gib Emby-Server-URL, Benutzername und Passwort ein und melde dich an. CrossWatch führt dich danach zu den Einstellungen, wo du den Server prüfst, den Benutzer wählst und optional Mediatheken freigibst.",
  "Enter your Emby server URL, username and password, then sign in. Next, validate the settings, pick the user, and optionally whitelist libraries.": "Gib Emby-Server-URL, Benutzername und Passwort ein und melde dich an. Prüfe danach die Einstellungen, wähle den Benutzer und gib optional Mediatheken frei.",
  "Enter your FlickList API key.": "Gib deinen FlickList-API-Schlüssel ein.",
  "Enter your Floppy API token": "Floppy-API-Token eingeben",
  "Enter your Jellyfin server URL, then connect with Quick Connect (recommended) or your username and password. CrossWatch will move you to Settings next so you can validate the server, pick the user, and optionally whitelist libraries.": "Gib deine Jellyfin-Server-URL ein und verbinde dich mit Quick Connect (empfohlen) oder mit Benutzername und Passwort. CrossWatch führt dich danach zu den Einstellungen, wo du den Server prüfst, den Benutzer wählst und optional Mediatheken freigibst.",
  "Enter your Jellyfin server URL, then connect with Quick Connect (recommended) or your username and password. Next, validate the settings, pick the user, and optionally whitelist libraries.": "Gib deine Jellyfin-Server-URL ein und verbinde dich mit Quick Connect (empfohlen) oder mit Benutzername und Passwort. Prüfe danach die Einstellungen, wähle den Benutzer und gib optional Mediatheken frei.",
  "Enter your Kitsu email or username and password": "Kitsu-E-Mail oder Benutzername und Passwort eingeben",
  "Enter your Kodi server URL and optional HTTP Basic Auth credentials. Make sure Kodi's web server and JSON RPC access are enabled before connecting.": "Gib deine Kodi-Server-URL und optional HTTP-Basic-Auth-Zugangsdaten ein. Stelle vor dem Verbinden sicher, dass der Webserver und der JSON-RPC-Zugriff von Kodi aktiviert sind.",
