  "History: Only items in destination library Skip movies and episodes that are not in the media server library. Matches on IDs only, so titles stored under a different ID are skipped too.": "Verlauf: Nur Elemente in der Ziel-Mediathek. Überspringt Filme und Episoden, die nicht in der Mediathek des Medienservers sind. Zuordnung nur über IDs, daher werden auch Titel mit einer anderen ID übersprungen.",
