  "I am reviewing an interactive sync for {0} before applying it. It proposes {1} changes: {2} removals, {3} conflicts and {4} that need attention.{5} Explain why CrossWatch proposes these changes, especially any removals, and whether anything looks risky to apply.": "Ich prüfe einen interaktiven Abgleich für {0}, bevor ich ihn übernehme. Er schlägt {1} Änderungen vor: {2} Entfernungen, {3} Konflikte und {4}, die Aufmerksamkeit brauchen.{5} Erkläre, warum CrossWatch diese Änderungen vorschlägt, besonders die Entfernungen, und ob etwas riskant aussieht.",
