  "Import {0} mapping/block records and {1} episode groups into their saved scopes? Episode groups include their completed-scrobble setting and require matching pairs and provider instances. Existing ordinary mappings are kept; conflicting episode groups reject the entire import. Current filters do not limit import.": "{0} Zuordnungs-/Sperr-Einträge und {1} Episodengruppen in ihre gespeicherten Bereiche importieren? Episodengruppen enthalten ihre Einstellung für abgeschlossene Scrobbles und setzen passende Paare und Anbieter-Instanzen voraus. Bestehende normale Zuordnungen bleiben erhalten, widersprüchliche Episodengruppen lassen den ganzen Import scheitern. Die aktuellen Filter schränken den Import nicht ein.",
