  "Improves anime matching for AniList and SIMKL pairs. Requires a TMDB metadata key.": "Verbessert die Anime-Zuordnung für AniList- und SIMKL-Paare. Setzt einen TMDB-Metadatenschlüssel voraus.",
  "Improves matching by translating AniList IDs to IDs your media servers and trackers understand.": "Verbessert die Zuordnung, indem AniList-IDs in IDs übersetzt werden, die deine Medienserver und Tracker verstehen.",
