  "Jellyfin Authentication": "Jellyfin-Anmeldung",
  "Jellyfin Settings": "Jellyfin-Einstellungen",
  "Jellyfin specifics": "Jellyfin-Besonderheiten",
  "Jellyfin webhook": "Jellyfin-Webhook",
  "Jellyfin Whitelisting": "Jellyfin-Freigabeliste",
  "Jellyfin: Strict ID matching": "Jellyfin: Strikter ID-Abgleich",
  "Jellyfin: Strict ID matching Require Jellyfin or external IDs to confirm matches. Title searches and legacy full-path matching are disabled. The pair Match by file path option can separately enable a file-path fallback. Episodes can match by series ID plus season and episode numbers.": "Jellyfin: Strikter ID-Abgleich. Treffer müssen über Jellyfin- oder externe IDs bestätigt werden. Titelsuchen und der alte Abgleich über den vollen Pfad sind deaktiviert. Die Paar-Option «Über Dateipfad zuordnen» kann separat einen Rückfall auf den Dateipfad aktivieren. Episoden können über die Serien-ID plus Staffel- und Episodennummer zugeordnet werden.",
  "Jellyfin: Targeted library lookup Match through a cached movie and series ID catalogue, then fetch episodes only for matched series. The catalogue checks for metadata changes on each sync that needs matching and refreshes fully every 24 hours. Disable to allow a full episode index. Title and path fallback require Strict ID matching to be off.": "Jellyfin: Gezielte Mediathek-Suche. Zuordnung über einen zwischengespeicherten Katalog von Film- und Serien-IDs, Episoden werden nur für zugeordnete Serien geladen. Der Katalog prüft bei jedem Abgleich, der eine Zuordnung braucht, auf Metadaten-Änderungen und wird alle 24 Stunden komplett erneuert. Deaktivieren, um einen vollständigen Episoden-Index zu erlauben. Der Rückfall auf Titel und Pfad setzt voraus, dass der strikte ID-Abgleich aus ist.",
  "Jellyfin: Watchlist mode Jellyfin has no native Watchlist. CrossWatch maps it to: • Favorites: sets the Favorite flag • Playlist: writes to a named playlist (episodes only; no shows) • Collections: writes to a named collection Changing mode does not move existing items. Tip: Favorites or Collections are the most compatible.": "Jellyfin: Watchlist-Modus. Jellyfin hat keine eigene Watchlist. CrossWatch bildet sie ab auf: • Favoriten: setzt die Favoriten-Markierung • Playlist: schreibt in eine benannte Playlist (nur Episoden, keine Serien) • Sammlungen: schreibt in eine benannte Sammlung. Ein Moduswechsel verschiebt bestehende Elemente nicht. Tipp: Favoriten oder Sammlungen sind am verträglichsten.",
  "Jobs and automation": "Aufgaben und Automatisierung",
  "Join the discussions and get help from the community.": "Nimm an den Diskussionen teil und hol dir Hilfe aus der Community.",
