  "Match by file path Applies only to this pair. When ID lookup fails, compare file-path endings between Plex, Jellyfin and Emby. Supports movies and episodes for history, ratings and progress, including with Strict ID matching enabled. Ambiguous paths and conflicting IDs are skipped. Off by default. The first lookup may take longer while the library catalogue is built.": "Über Dateipfad zuordnen: Gilt nur für dieses Paar. Wenn die ID-Suche scheitert, werden die Enden der Dateipfade zwischen Plex, Jellyfin und Emby verglichen. Unterstützt Filme und Episoden für Verlauf, Bewertungen und Fortschritt, auch mit aktivem striktem ID-Abgleich. Mehrdeutige Pfade und widersprüchliche IDs werden übersprungen. Standardmässig aus. Die erste Suche kann länger dauern, während der Mediathek-Katalog aufgebaut wird.",
