  "Progress is unavailable. Reopen the review to reconnect.": "Fortschritt nicht verfügbar. Öffne die Prüfung erneut, um wieder zu verbinden.",
  "Progress per month": "Fortschritt pro Monat",
  "Progress percent": "Fortschritt in Prozent",
  "Progress percentage that counts an item as watched for completion and auto-remove. Route options can override it.": "Fortschritt in Prozent, ab dem ein Element für Abschluss und automatisches Entfernen als gesehen gilt. Routen-Optionen können das übersteuern.",
  "Progress percentage that counts an item as watched for this route.": "Fortschritt in Prozent, ab dem ein Element für diese Route als gesehen gilt.",
  "Progress step (%)": "Fortschrittsschritt (%)",
