  "Progress sync": "Fortschritts-Abgleich",
  "Progress updates automatically as providers report activity.": "Der Fortschritt aktualisiert sich automatisch, sobald Anbieter Aktivität melden.",
  "Progress | Basics": "Fortschritt | Grundlagen",
  "Progress | Options": "Fortschritt | Optionen",
  "Progress, status and next steps": "Fortschritt, Status und nächste Schritte",
  "Progress: Add / Update Write resume position to the target.": "Fortschritt: Hinzufügen / Aktualisieren. Schreibt die Wiedergabeposition ins Ziel.",
  "Progress: Change threshold Only write when the difference is large enough.": "Fortschritt: Änderungsschwelle. Nur schreiben, wenn der Unterschied gross genug ist.",
  "Progress: Enable Sync resume position (where you left off) between providers.": "Fortschritt: Aktivieren. Wiedergabeposition (wo du aufgehört hast) zwischen Anbietern abgleichen.",
  "Progress: Ignore near complete (%) One-way defaults to the target recommendation. Two-way keeps one shared limit and shows per-target recommendations below.": "Fortschritt: Fast fertig ignorieren (%). Einseitig gilt standardmässig die Empfehlung des Ziels. Beidseitig gilt eine gemeinsame Grenze, die Empfehlungen pro Ziel stehen unten.",
  "Progress: Minimum seconds Ignore tiny offsets (scrubbing).": "Fortschritt: Mindestsekunden. Kleine Abweichungen (Spulen) ignorieren.",
  "Progress: Only items in destination library Skip resume positions for movies and episodes that are not in the media server library. Titles the server already has a position for are always synced. Matches on IDs only, so titles stored under a different ID are skipped too.": "Fortschritt: Nur Elemente in der Ziel-Mediathek. Überspringt Wiedergabepositionen für Filme und Episoden, die nicht in der Mediathek des Medienservers sind. Titel, für die der Server schon eine Position hat, werden immer abgeglichen. Zuordnung nur über IDs, daher werden auch Titel mit einer anderen ID übersprungen.",
  "Progress: Remove Clear resume position on the target (rare; Plex may not support).": "Fortschritt: Entfernen. Löscht die Wiedergabeposition am Ziel (selten, Plex unterstützt es eventuell nicht).",
  "Progress: Specials (Season 0) Include Season 0 / specials episodes. Disable to skip them on both sides of this pair.": "Fortschritt: Specials (Staffel 0). Staffel 0 / Special-Episoden einbeziehen. Deaktivieren, um sie auf beiden Seiten dieses Paars zu überspringen.",
  "Promote after (failed writes)": "In Blackbox nach (fehlgeschlagenen Schreibvorgängen)",
  "Promote after (failed writes) Number of consecutive failed write attempts before an item is moved to the blackbox. Until then the item keeps being retried; unresolved alone never blocks it.": "In Blackbox nach (fehlgeschlagenen Schreibvorgängen): Anzahl aufeinanderfolgender fehlgeschlagener Schreibversuche, bevor ein Element in die Blackbox kommt. Bis dahin wird es weiter versucht, «offen» allein sperrt es nie.",
  "Promoted to blackbox after repeated failures": "Nach mehreren Fehlern in die Blackbox verschoben",
