  "Ratings: Enable Compare and write ratings to the target.": "Bewertungen: Aktivieren. Bewertungen vergleichen und ins Ziel schreiben.",
  "Ratings: Only items in destination library Skip new ratings for movies and episodes that are not in the media server library. Rating changes for titles you already rated are always synced. Matches on IDs only, so titles stored under a different ID are skipped too.": "Bewertungen: Nur Elemente in der Ziel-Mediathek. Überspringt neue Bewertungen für Filme und Episoden, die nicht in der Mediathek des Medienservers sind. Änderungen an Titeln, die du schon bewertet hast, werden immer abgeglichen. Zuordnung nur über IDs, daher werden auch Titel mit einer anderen ID übersprungen.",
  "Ratings: Remove Clears ratings on the target (destructive and only for very specific needs).": "Bewertungen: Entfernen. Löscht Bewertungen am Ziel (zerstörerisch, nur für sehr spezielle Fälle).",
  "Ratings: Specials (Season 0) Include Season 0 / specials seasons and episodes. Disable to skip them on both sides of this pair.": "Bewertungen: Specials (Staffel 0). Staffel 0 / Special-Staffeln und -Episoden einbeziehen. Deaktivieren, um sie auf beiden Seiten dieses Paars zu überspringen.",
