  "Reads the Tautulli history and uses the Plex account only to look up IDs, including for items removed from Plex.": "Liest den Tautulli-Verlauf und nutzt das Plex-Konto nur zur ID-Suche, auch für Elemente, die aus Plex entfernt wurden.",
