  "Rebuild archive · {0} events rebuilt from runtime state.": "Archiv neu aufgebaut · {0} Ereignisse aus dem Laufzeit-Zustand neu erstellt.",
  "Rebuild index": "Index neu aufbauen",
  "Rebuild local database": "Lokale Datenbank neu aufbauen",
  "Rebuild local database completed · {0}.": "Lokale Datenbank neu aufgebaut · {0}.",
  "Rebuild reports and refresh cached metadata.": "Berichte neu aufbauen und zwischengespeicherte Metadaten aktualisieren.",
  "Rebuild statistics": "Statistik neu aufbauen",
  "Rebuild sync state": "Abgleich-Zustand neu aufbauen",
  "Rebuild the local database? The current database files are moved to .cw_databases/backups and a fresh database is created. Sync baselines, Editor mappings and blocks, Events, statistics, sync reports and hidden watchlist items start empty. config.json and provider logins stay. The next sync works like a first sync: nothing is deleted, but a two-way pair can add back items removed on one side.": "Lokale Datenbank neu aufbauen? Die aktuellen Datenbankdateien werden nach .cw_databases/backups verschoben, und eine neue Datenbank wird erstellt. Abgleich-Basisdaten, Editor-Zuordnungen und -Sperren, Ereignisse, Statistik, Abgleichberichte und ausgeblendete Watchlist-Elemente beginnen leer. config.json und Anbieter-Anmeldungen bleiben. Der nächste Abgleich verhält sich wie ein erster: Es wird nichts gelöscht, aber ein beidseitiges Paar kann Elemente wieder hinzufügen, die auf einer Seite entfernt wurden.",
  "Rebuilding": "Baue neu auf",
  "Rebuilding state.json": "Baue state.json neu auf",
  "Rebuilding state.json...": "Baue state.json neu auf...",
  "Rebuilding sync state from the database...": "Baue Abgleich-Zustand aus der Datenbank neu auf...",
