  "Remove the saved mapping for this item? This undoes the correction and lifts the block on the original item.": "Gespeicherte Zuordnung für dieses Element entfernen? Das macht die Korrektur rückgängig und hebt die Sperre des Originalelements auf.",
  "Remove the saved mapping for {0} from {1}? Its automatic original-item block will also be removed. Other mappings may apply again. This does not undo synced media changes.": "Gespeicherte Zuordnung für {0} aus {1} entfernen? Die automatische Sperre des Originalelements wird ebenfalls entfernt. Andere Zuordnungen können wieder greifen. Bereits abgeglichene Medienänderungen werden nicht rückgängig gemacht.",
