  "Removes cached artwork and metadata so fresh copies are fetched when needed.": "Entfernt zwischengespeicherte Bilder und Metadaten, damit bei Bedarf frische Kopien geladen werden.",
  "Removes history using each provider’s sync removal behavior. Selecting a whole title removes that movie or episode; FLOPPY removes its latest watch. Selecting single watches removes only those watches, and only on profiles that keep separate watches; other profiles are skipped for them. Other sync sources or saved additions can restore removed records.": "Entfernt den Verlauf gemäss dem Entfernungsverhalten jedes Anbieters. Wählst du einen ganzen Titel, wird dieser Film oder diese Episode entfernt, FLOPPY entfernt die letzte Sichtung. Wählst du einzelne Sichtungen, werden nur diese entfernt, und nur bei Profilen, die getrennte Sichtungen führen, andere Profile werden dafür übersprungen. Andere Abgleichquellen oder gespeicherte Ergänzungen können entfernte Einträge wiederherstellen.",
  "Removes stuck items from the local Currently Playing list.": "Entfernt hängende Elemente aus der lokalen Liste «Läuft gerade».",
  "Removes the selected ratings from the chosen providers.": "Entfernt die ausgewählten Bewertungen bei den gewählten Anbietern.",
  "Removes the selected records from the chosen profiles. Other sync sources or saved additions can restore them. Mappings and blocks stay in place.": "Entfernt die ausgewählten Einträge aus den gewählten Profilen. Andere Abgleichquellen oder gespeicherte Ergänzungen können sie wiederherstellen. Zuordnungen und Sperren bleiben bestehen.",
  "Removes the selected titles from the chosen provider collections.": "Entfernt die ausgewählten Titel aus den Sammlungen der gewählten Anbieter.",
  "Removes the selected titles from the chosen provider watchlists.": "Entfernt die ausgewählten Titel aus den Watchlists der gewählten Anbieter.",
