  "Review matches before importing. Other search providers can identify titles, but cannot retrieve history Plex no longer exposes.": "Prüfe die Treffer vor dem Import. Andere Such-Anbieter können Titel erkennen, aber keinen Verlauf abrufen, den Plex nicht mehr anbietet.",
  "Review recent results": "Letzte Ergebnisse prüfen",
  "Review recommended": "Prüfung empfohlen",
  "Review the affected items below.": "Prüfe die betroffenen Elemente unten.",
  "Review the group's watched-part counts and any hold reason. Manage this rule in Editor → Mappings & blocks → Episode groups. Incomplete separate parts must all be watched before the combined episode can be added.": "Prüfe die Anzahl gesehener Teile der Gruppe und allfällige Gründe fürs Zurückhalten. Verwalte diese Regel unter Editor → Zuordnungen und Sperren → Episodengruppen. Unvollständige Einzelteile müssen alle gesehen sein, bevor die kombinierte Episode hinzugefügt werden kann.",
  "Review the provider's reported reason and the pair's sync rules. Correct the mapping only if the item was identified incorrectly.": "Prüfe den vom Anbieter gemeldeten Grund und die Abgleichregeln des Paars. Korrigiere die Zuordnung nur, wenn das Element falsch erkannt wurde.",
  "Review the schedule": "Zeitplan prüfen",
  "Review the tracker before retrying the file.": "Prüfe den Tracker, bevor du die Datei erneut versuchst.",
  "Review the upgrade note below": "Prüfe den Upgrade-Hinweis unten",
  "Review this ruleset as readable behaviour. Built in rulesets can be cloned, but not edited.": "Prüfe diesen Regelsatz als lesbares Verhalten. Eingebaute Regelsätze können dupliziert, aber nicht bearbeitet werden.",
  "Review title guesses individually or use Accept all title matches. Select all matching skips unaccepted guesses. Repeated records are combined into one item using the most recent watch date.": "Prüfe Titel-Vermutungen einzeln oder nutze «Alle Titel-Treffer übernehmen». «Alle passenden auswählen» überspringt nicht übernommene Vermutungen. Wiederholte Einträge werden mit dem jüngsten Sichtungsdatum zu einem Element zusammengefasst.",
  "Review title match": "Titel-Treffer prüfen",
  "Review which provider should supply this feature. This is a potential conflict, not evidence that values have been overwritten.": "Prüfe, welcher Anbieter diese Funktion liefern soll. Dies ist ein möglicher Konflikt, kein Beweis, dass Werte überschrieben wurden.",
