  "Secondary actions for selected captures.": "Weitere Aktionen für ausgewählte Erfassungen.",
  "Seconds between checks while nothing is playing, from 5 to 120. This decides how quickly a new playback is noticed. It never drops below the poll interval. Routes sharing this source use the lowest value set.": "Sekunden zwischen den Prüfungen, solange nichts läuft, von 5 bis 120. Bestimmt, wie schnell eine neue Wiedergabe bemerkt wird. Nie weniger als das Abfrageintervall. Routen mit derselben Quelle nutzen den kleinsten Wert.",
  "Seconds between playback checks while something is playing, from 5 to 60. Higher values lower the load but delay pause and stop detection. Routes sharing this source use the lowest value set.": "Sekunden zwischen den Wiedergabe-Prüfungen, solange etwas läuft, von 5 bis 60. Höhere Werte senken die Last, verzögern aber das Erkennen von Pause und Stopp. Routen mit derselben Quelle nutzen den kleinsten Wert.",
  "Seconds to ignore tiny pause/start flaps just after playback starts for this route.": "Sekunden, in denen kurzes Pause/Start-Flattern direkt nach Wiedergabebeginn für diese Route ignoriert wird.",
