  "The example follows multiple pairs back to its starting provider. CrossWatch has safeguards, so this does not imply an infinite loop; the additional route may cause extra provider activity.": "Das Beispiel folgt mehreren Paaren zurück zum Ausgangs-Anbieter. CrossWatch hat Schutzmechanismen, das bedeutet also keine Endlosschleife, die zusätzliche Route kann aber zusätzliche Anbieter-Aktivität verursachen.",
