  "The provider did not record the scrobble, nothing went wrong.": "Der Anbieter hat den Scrobble nicht erfasst, es ist nichts schiefgegangen.",
  "The provider lists CrossWatch can sync.": "Die Anbieter-Listen, die CrossWatch abgleichen kann.",
