  "This sync pair does not have a managed playlist mapping assigned.": "Diesem Sync-Paar ist keine verwaltete Playlist-Zuordnung zugewiesen.",
  "This sync pair is owned by {0}. Normal pair editing is disabled so the playlist mapping stays connected.": "Dieses Sync-Paar gehört zu {0}. Die normale Bearbeitung ist deaktiviert, damit die Playlist-Zuordnung verbunden bleibt.",
  "This topology is valid. Keep the routes you need and consider consolidating pairs that serve the same purpose.": "Diese Topologie ist gültig. Behalte die Routen, die du brauchst, und erwäge, Paare mit demselben Zweck zusammenzulegen.",
