  "Two-way pairs": "Beidseitige Paare",
  "Two-way sync does not make the configured source authoritative. Keep these pairs if changes should flow both ways; use one-way pairs if only the source should send changes.": "Ein beidseitiger Abgleich macht die eingerichtete Quelle nicht massgebend. Behalte diese Paare, wenn Änderungen in beide Richtungen fliessen sollen, nutze einseitige Paare, wenn nur die Quelle Änderungen senden soll.",
  "Two-way sync finished": "Beidseitiger Abgleich beendet",
  "Two-way sync means both sides can write to each other. It keeps both providers aligned, but it also heavily increases the risk of conflicts, duplicates, overwrites, and deletions. Use with extreme caution.": "Beidseitiger Abgleich bedeutet, dass beide Seiten gegenseitig schreiben können. Das hält beide Anbieter abgestimmt, erhöht aber stark das Risiko von Konflikten, Duplikaten, Überschreibungen und Löschungen. Mit äusserster Vorsicht verwenden.",
  "Two-way sync started": "Beidseitiger Abgleich gestartet",
