  "Unresolved is a reporting state: failed writes are logged and retried every sync. Blackbox is the quarantine state: after this many failed writes an item is blackboxed and only then stops being planned.": "«Offen» ist ein Berichtsstatus: Fehlgeschlagene Schreibvorgänge werden protokolliert und bei jedem Abgleich erneut versucht. Blackbox ist der Quarantäne-Status: Nach so vielen fehlgeschlagenen Schreibvorgängen kommt ein Element in die Blackbox und wird erst dann nicht mehr eingeplant.",
