  "Uploading, detecting the format and checking for existing items. Large files can take a little longer. Nothing is imported during preview.": "Lade hoch, erkenne das Format und prüfe auf vorhandene Elemente. Grosse Dateien brauchen etwas länger. Während der Vorschau wird nichts importiert.",
  "Use 0 to keep episode numbers, or a shift such as −10 to change episode 11 to 1. Applies to selected episodes.": "Nutze 0, um die Episodennummern zu behalten, oder eine Verschiebung wie −10, um Episode 11 zu 1 zu machen. Gilt für die ausgewählten Episoden.",
