  "Use Anime ID Mapping Use the local Anime ID database to match anime for this watchlist pair. Requires global Anime ID Mapping to be enabled first.": "Anime-ID-Zuordnung verwenden: Die lokale Anime-ID-Datenbank nutzen, um Anime für dieses Watchlist-Paar zuzuordnen. Setzt voraus, dass die globale Anime-ID-Zuordnung aktiviert ist.",
