  "Use Nuvio TV login, approve the temporary code, then choose a profile. Nuvio API contracts may change.": "Nutze die Nuvio-TV-Anmeldung, bestätige den temporären Code und wähle dann ein Profil. Die Nuvio-API kann sich ändern.",
