  "Use standard plan: Turn on the standard timer-based scheduler. When enabled, the advanced plan is turned off.": "Standardplan verwenden: Schaltet den normalen Zeitplaner mit Timer ein. Wenn aktiv, wird der erweiterte Plan ausgeschaltet.",
  "Use the approval link to open MyAnimeList.": "Öffne MyAnimeList über den Freigabelink.",
