  "Use the configured Plex username when Plex omits the playback user and the session cannot be resolved.": "Den eingerichteten Plex-Benutzernamen verwenden, wenn Plex den Wiedergabe-Benutzer weglässt und die Sitzung nicht aufgelöst werden kann.",
  "Use the local Anime ID mapping index": "Lokalen Anime-ID-Zuordnungsindex verwenden",
  "Use the local mapping datasets to translate anime identifiers and episode numbering between AniDB, MyAnimeList, AniList, Kitsu, SIMKL, TMDb and TVDb.": "Die lokalen Zuordnungsdatensätze nutzen, um Anime-Kennungen und Episodennummerierung zwischen AniDB, MyAnimeList, AniList, Kitsu, SIMKL, TMDb und TVDb umzurechnen.",
