  "Watchlist widget: Shows or hides the dashboard Watchlist card on the Main screen.": "Watchlist-Widget: Zeigt oder verbirgt die Watchlist-Karte auf dem Startbildschirm.",
  "Watchlist | Basics": "Watchlist | Grundlagen",
  "Watchlist | Options": "Watchlist | Optionen",
  "Watchlist: Add Adds missing items to the target watchlist.": "Watchlist: Hinzufügen. Fügt fehlende Elemente zur Watchlist des Ziels hinzu.",
  "Watchlist: Enable Compare watchlists and write missing items to the target.": "Watchlist: Aktivieren. Watchlists vergleichen und fehlende Elemente ins Ziel schreiben.",
  "Watchlist: Only items in destination library Skip watchlist items that are not in the media server library. Useful for large tracker watchlists, where most titles are not in your library yet. Matches on IDs only, so titles stored under a different ID are skipped too.": "Watchlist: Nur Elemente in der Ziel-Mediathek. Überspringt Watchlist-Elemente, die nicht in der Mediathek des Medienservers sind. Nützlich für grosse Tracker-Watchlists, bei denen die meisten Titel noch nicht in deiner Mediathek sind. Zuordnung nur über IDs, daher werden auch Titel mit einer anderen ID übersprungen.",
  "Watchlist: Remove Removes items from the target.": "Watchlist: Entfernen. Entfernt Elemente im Ziel.",
