  "When a provider you use needs a new sign-in, and again when it works.": "Wenn ein genutzter Anbieter eine neue Anmeldung braucht, und nochmals, wenn es wieder funktioniert.",
  "When an enabled watcher route is not running, and again when it is back.": "Wenn eine aktive Watcher-Route nicht läuft, und nochmals, wenn sie wieder läuft.",
  "When IDs cannot resolve an item, try matching its file path across the media servers in this pair. Supports movie and episode history, ratings and progress in both directions, including with Strict ID matching enabled.": "Wenn IDs ein Element nicht auflösen können, wird versucht, es über den Dateipfad zwischen den Medienservern dieses Paars zuzuordnen. Unterstützt Verlauf, Bewertungen und Fortschritt von Filmen und Episoden in beide Richtungen, auch mit aktivem striktem ID-Abgleich.",
  "When the item is": "Wenn das Element",
  "When the same title exists more than once, for example in a regular and a 4K library, update every copy instead of skipping.": "Wenn derselbe Titel mehrfach existiert, etwa in einer normalen und einer 4K-Mediathek, jede Kopie aktualisieren statt zu überspringen.",
  "When the source contains more than {0} items, CrossWatch splits the content into target lists containing up to {1} items each.": "Wenn die Quelle mehr als {0} Elemente enthält, verteilt CrossWatch den Inhalt auf Ziellisten mit je bis zu {1} Elementen.",
