  "With a cloud provider, your questions and the log lines and settings needed to answer them go to that provider. Secrets are removed first. A local model keeps everything at home.": "Bei einem Cloud-Anbieter gehen deine Fragen sowie die zur Antwort nötigen Protokollzeilen und Einstellungen an diesen Anbieter. Geheimnisse werden vorher entfernt. Ein lokales Modell behält alles zu Hause.",
