  "{0} h ago": "vor {0} h",
  "{0} help": "Hilfe zu {0}",
  "{0} history supports both directions and is anime only. It uses watched status and episode progress per title. Remove reduces progress only for the latest watched episodes, or resets a movie to unwatched; ratings and notes are preserved. Gaps are reported unresolved. Specials and rewatches are skipped.": "{0}-Verlauf unterstützt beide Richtungen und nur Anime. Er nutzt pro Titel den Gesehen-Status und den Episodenfortschritt. Entfernen reduziert den Fortschritt nur für die zuletzt gesehenen Episoden oder setzt einen Film auf ungesehen zurück, Bewertungen und Notizen bleiben erhalten. Lücken werden als offen gemeldet. Specials und wiederholte Sichtungen werden übersprungen.",
  "{0} hours ago": "vor {0} Stunden",
  "{0} hour{1}": "{0} Stunde(n)",
  "{0} IDs differ. Confirm this is the same title before saving.": "{0}-IDs weichen ab. Bestätige vor dem Speichern, dass es derselbe Titel ist.",
  "{0} instances": "{0} Instanzen",
  "{0} is a Plex friend/shared account, not a Plex Home user. CrossWatch can only use Plex's server-scoped shared token for History and Progress. Ratings and Watchlist still need that friend's own Plex profile/authentication, and Plex may remove this token path later.": "{0} ist ein Plex-Freund/geteiltes Konto, kein Plex-Home-Benutzer. CrossWatch kann für Verlauf und Fortschritt nur das servergebundene geteilte Token von Plex nutzen. Bewertungen und Watchlist brauchen weiterhin das eigene Plex-Profil bzw. die Anmeldung dieses Freundes, und Plex könnte diesen Token-Weg später entfernen.",
  "{0} is always shown": "{0} wird immer angezeigt",
