  "{0} items were excluded by saved mappings or Editor rules. Old identities stay excluded so their corrected replacements can sync. These exclusions are not failed sync attempts.": "{0} Elemente wurden durch gespeicherte Zuordnungen oder Editor-Regeln ausgeschlossen. Alte Kennungen bleiben ausgeschlossen, damit ihre korrigierten Ersatzeinträge abgeglichen werden können. Diese Ausschlüsse sind keine fehlgeschlagenen Abgleichversuche.",
